import type { ReactNode } from 'react'

/**
 * SESSION 6 SHARED PREAMBLE — "Pushing Image to Docker Hub"
 *
 * Every slide in this deck reads its constants, helpers and transcripts from
 * here. It exists because this deck was generated by four parallel agents, and
 * a shared contract is the only thing that makes four authors produce one deck:
 * the same session name, the same concept strings, the same `Code` chip, the
 * same Docker ID, and one copy of every transcript that appears twice.
 *
 * Only the three part files and `dockerHubDeck.tsx` may import it. Anything that
 * appears on more than one slide belongs here rather than copied into two parts:
 * that is the whole mechanism keeping four authors' work consistent.
 */

export const SESSION = 'Pushing Image to Docker Hub'
export const COURSE = 'React + Django Integration · Deployment'

