export const REPO = `${DOCKER_ID}/${IMAGE}`

/**
 * Inline code, at body size, on a light slide.
 *
 * A `<code>` in running text is not `CodeBlock`: it carries no panel, no chip
 * and no line numbers. Session 5 defined this helper for the same reason and
 * this deck keeps it identical, so a command reads the same in both decks.
 */
export function Code({ children }: { children: ReactNode }) {
  return (
    <code className="rounded-md bg-surface-2 px-1.5 py-0.5 font-mono text-[0.94em] text-brand-deep">
      {children}
    </code>
  )
}

/**
 * TECHNOLOGY LOGOS, AS A STATIC MAP.
 *
 * The paths are literals and have to be. `scripts/inline-assets.mjs` finds
 * assets by scanning the built HTML for literal `/assets/...` strings, so a
 * template literal (`/assets/tech/${name}.png`) survives dev and `build` and
 * then ships a broken image in the single-file deck the instructor opens.
 * Session 3 shipped exactly that bug.
 *
 * Trimmed to what this deck renders: every entry is inlined whether or not a
 * slide uses it, and session 4 measured ten unused logos at 290 KB.
 */
const TECH_SRC = {
  docker: '/assets/tech/docker.png',
  python: '/assets/tech/python.png',
  nodejs: '/assets/tech/nodejs.png',
  git: '/assets/tech/git.png',
  makefile: '/assets/tech/makefile.png',
} as const

/** A logo with its name beside it. The mark supports the label, never replaces it. */
export function Tech({
  name,
  label,
  size = 20,
}: {
  name: keyof typeof TECH_SRC
  label?: string
  size?: number
}) {
  return (
    <span className="inline-flex items-center gap-2">
      <img
        src={TECH_SRC[name]}
        alt=""
        draggable={false}
        style={{ height: size, width: size }}
        className="object-contain"
      />
      {label ? <span>{label}</span> : null}
    </span>
  )
}

